// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.sttimport timber.log.Timberimport java.util.concurrent.atomic.AtomicReference/** * NOUS — Delta Context Updater (v2 review fix #6). * * Streaming STT emits a partial result every ~200 ms containing the *full* * text so far. If the Brain regenerated its full prompt each time, we'd * spam the LLM with 5 near-identical requests per second — costly, slow, * and it busts the cloud-LLM rate limit. * * This class converts the stream of "full text so far" partials into * **append-only deltas**: only the new words get passed to the Brain. When * STT corrects previous text (rare — happens when the recognizer revises * its hypothesis), we emit a single REPLACE delta so the Brain can rebuild * context from scratch. * * ## Algorithm (§19 Delta Context Updater) * * ``` * newPartialText arrives *     ↓ * if (newPartialText == lastPartialText) → return null (no change) *     ↓ * if (newPartialText.startsWith(lastPartialText)) *     → APPEND: delta = newPartialText.removePrefix(lastPartialText) *     ↓ * else *     → REPLACE: STT corrected previous text, Brain must rebuild * ``` * * ## Brain integration * * Per the v2 strategy doc: *  - Brain processes **APPEND** deltas incrementally (cheap — no LLM call). *  - Brain processes **REPLACE** deltas by rebuilding the user-turn buffer *    (still no LLM call — the Brain only invokes the LLM when the STT emits *    a [SttResult.Final]). * * ## Thread safety * * [AtomicReference] holds the last partial text so calls from multiple * threads (the STT engine may emit from a recognizer callback thread) are * safe. The compare-and-set loop guarantees no delta is lost even under * concurrent updates — though in practice STT engines are single-threaded. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§19 Delta Context Updater — v2 Fix #6</a> */class DeltaContextUpdater {    private val lastPartialRef = AtomicReference("")    /** The most recent partial text seen by this updater. */    val lastPartialText: String get() = lastPartialRef.get()    /**     * Process a new partial STT result.     *     * @param newPartialText latest partial STT result (full text so far).     * @return [DeltaUpdate] describing what changed, or `null` if no change.     */    fun processDelta(newPartialText: String): DeltaUpdate? {        // CAS loop: ensure we always emit a delta consistent with the        // lastPartialText we read, even if another thread updates between        // our read and our write.        while (true) {            val current = lastPartialRef.get()            if (newPartialText == current) return null  // no change            if (lastPartialRef.compareAndSet(current, newPartialText)) {                return when {                    current.isEmpty() -> {                        // First partial of a new utterance — treat as APPEND                        // so the Brain can start a fresh user-turn buffer.                        DeltaUpdate(                            type = DeltaType.APPEND,                            newWords = newPartialText,                            fullText = newPartialText,                        )                    }                    newPartialText.startsWith(current) -> {                        // Common case: STT appended new words.                        val delta = newPartialText.removePrefix(current)                        DeltaUpdate(                            type = DeltaType.APPEND,                            newWords = delta,                            fullText = newPartialText,                        )                    }                    else -> {                        // STT revised earlier text — full replace.                        Timber.tag(TAG).d("STT revised earlier text — emitting REPLACE delta.")                        DeltaUpdate(                            type = DeltaType.REPLACE,                            newWords = newPartialText,                            fullText = newPartialText,                        )                    }                }            }            // CAS failed — another thread updated lastPartialRef; retry.        }    }    /**     * Reset the updater for a new utterance. Called after the STT emits a     * [SttResult.Final] so the next utterance starts fresh.     */    fun reset() {        lastPartialRef.set("")    }    // ──────────────────────────────────────────────────────────────────────    /**     * One delta update emitted by [processDelta].     *     * @param type     APPEND = new words only; REPLACE = full text changed.     * @param newWords for APPEND: just the new words. For REPLACE: the full     *                 revised text (Brain uses this to rebuild context).     * @param fullText the complete partial text after this update.     */    data class DeltaUpdate(        val type: DeltaType,        val newWords: String,        val fullText: String,    )    /** Type of delta update. */    enum class DeltaType {        /** New words were appended — Brain can extend the user-turn buffer cheaply. */        APPEND,        /** STT revised earlier text — Brain must rebuild the user-turn buffer. */        REPLACE,    }    private companion object {        private const val TAG = "DeltaCtxUpdater"    }}